test("day zero on the denial date is allowed with 120 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" }), { allowed: true, daysLeft: 120, elapsedDays: 0 });
});
test("one day after the denial date is allowed with 119 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-11" }), { allowed: true, daysLeft: 119, elapsedDays: 1 });
});
test("January 10 to March 10 across a non-leap February is allowed with 61 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" }), { allowed: true, daysLeft: 61, elapsedDays: 59 });
});
test("one day before day 120 is allowed with 1 day left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-09" }), { allowed: true, daysLeft: 1, elapsedDays: 119 });
});
test("day 120 is still allowed with 0 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" }), { allowed: true, daysLeft: 0, elapsedDays: 120 });
});
test("one day past day 120 is closed with 0 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" }), { allowed: false, daysLeft: 0, elapsedDays: 121 });
});
test("first through last day of a 31 day month leaves 90 days", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-03-01", checkDate: "2026-03-31" }), { allowed: true, daysLeft: 90, elapsedDays: 30 });
});
test("December 1 to January 31 across the year boundary leaves 59 days", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2025-12-01", checkDate: "2026-01-31" }), { allowed: true, daysLeft: 59, elapsedDays: 61 });
});
test("last day of December to January 1 is allowed with 119 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2025-12-31", checkDate: "2026-01-01" }), { allowed: true, daysLeft: 119, elapsedDays: 1 });
});
test("February 1 to March 1 in a leap year is allowed with 91 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2024-02-01", checkDate: "2024-03-01" }), { allowed: true, daysLeft: 91, elapsedDays: 29 });
});
test("leap day as the denial date to the next day is allowed with 119 days left", function () {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2024-02-29", checkDate: "2024-03-01" }), { allowed: true, daysLeft: 119, elapsedDays: 1 });
});
test("February 29 in a non-leap year is an invalid denial date", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-02-29", checkDate: "2026-03-01" });
  }, /^invalid date: denialDate$/);
});
test("April 31 is an invalid check date", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-04-01", checkDate: "2026-04-31" });
  }, /^invalid date: checkDate$/);
});
test("missing denial date is rejected", function () {
  assert.throws(function () {
    code.checkAppealWindow({ checkDate: "2026-01-10" });
  }, /^missing field: denialDate$/);
});
test("missing check date is rejected", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10" });
  }, /^missing field: checkDate$/);
});
test("an unknown field is rejected", function () {
  assert.throws(function () {
    code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10", note: "x" });
  }, /^unknown field: note$/);
});
